      "topic": "응용 계층",
      "detail": "HTTP",
      "meaning": "HTTP는 응용 계층에서 다양한 정보를 주고받는 데 사용되는 프로토콜이에요. 클라이언트-서버 구조 기반의 요청-응답 프로토콜이에요. 주고받을 미디어 타입에 특별히 제한을 두지 않고 독립적으로 동작이 가능한 미디어 독립적인 프로토콜이에요.",
