      "term": "미디어 타입",
      "english": "media type",
      "topic": "응용 계층",
      "detail": "HTTP",
      "meaning": "미디어 타입은 HTTP에서 메시지로 주고받는 자원의 종류로 일종의 웹 세상의 확장자와 같은 개념이에요. '타입/서브타입(type/subtype)' 형식으로 구성되며, 타입은 데이터의 유형을 나타내고, 서브타입은 주어진 타입에 대한 세부 유형을 나타냄이에요.",
