      "term": "HTTP/1.0",
      "english": "",
      "topic": "응용 계층",
      "detail": "HTTP",
      "meaning": "HTTP/1.0은 HEAD, POST와 같은 GET 이외의 메서드가 도입된 HTTP 버전이에요. 헤더가 지원되기 시작해 훨씬 더 다양한 정보를 주고 받을 수 있게 돼요. 하지만 공식적으로 지속 연결(persistent connection)을 지원하지 않음이에요.",
