      "subject": "net",
      "term": "HTTP/1.1",
      "english": "",
      "topic": "응용 계층",
      "detail": "HTTP",
      "meaning": "HTTP/1.1은 지속 연결이 공식적으로 지원된 HTTP 버전이에요. 특정 요청에 대한 응답이 수신되기 전에 다음 요청을 보낼 수 있는 파이프라이닝 기능 지원해요. 콘텐츠 협상 기능 등 다양한 편의 기능 및 사용 가능한 헤더가 추가돼요.",
