      "subject": "net",
      "term": "HTTP/2.0",
      "english": "",
      "topic": "응용 계층",
      "detail": "HTTP",
      "meaning": "HTTP/2.0은 송수신 효율을 높이기 위해 헤더를 압축하여 전송하고, (텍스트 기반의 메시지를 송수신한 이전 버전과는 달리) 바이너리 데이터 기반의 메시지를 송수신하며 서버 푸시라는 기능을 제공하고 HOL 블로킹이라는 문제를 완화한 HTTP 버전이에요.",
